
.app-screen {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: var(--c-phone-screen);
  min-height: 0;
  position: relative;
}

.app-header {
  flex: none;
  height: 48px;
  display: flex;
  align-items: center;
  padding: 0 12px;
  background: rgba(255, 255, 255, 0.75);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--c-separator);

  .back-btn {
    width: 34px;
    height: 34px;
    border-radius: 50%;
    color: var(--c-ios-blue);
    font-size: 15px;
  }

  .app-title {
    flex: 1;
    text-align: center;
    font-size: 16px;
    font-weight: 700;
    transform: translateX(-17px);
  }
}

.thread-list {
  flex: 1;
  overflow-y: auto;
}

.thread-item {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  background: #fff;
  text-align: left;

  & + .thread-item {
    border-top: 1px solid var(--c-separator);
  }

  &:active {
    background: #f2f2f7;
  }
}

.avatar {
  width: 46px;
  height: 46px;
  flex: none;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 18px;
  font-weight: 700;
}

.thread-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.thread-name {
  font-size: 15px;
  font-weight: 700;
}

.thread-preview {
  font-size: 13px;
  color: var(--c-ios-gray);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.thread-arrow {
  color: #c7c7cc;
  font-size: 13px;
}

.unread-badge {
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border-radius: 10px;
  background: #ff3b30;
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
}

.empty-hint {
  padding: 40px 24px;
  text-align: center;
  font-size: 13px;
  color: var(--c-ios-gray);
}

.bubble-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 14px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.bubble-row {
  display: flex;

  &.me {
    justify-content: flex-end;
  }

  &.them {
    justify-content: flex-start;
  }
}

.bubble {
  max-width: 74%;
  padding: 8px 13px;
  border-radius: 18px;
  font-size: 14px;
  line-height: 1.5;
  word-break: break-word;

  .me & {
    background: var(--c-ios-blue);
    color: #fff;
    border-bottom-right-radius: 4px;
  }

  .them & {
    background: var(--c-bubble-other);
    color: var(--c-text);
    border-bottom-left-radius: 4px;
  }

  &.typing {
    display: flex;
    gap: 4px;
    padding: 12px 14px;

    i {
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: #9c9ca1;
      animation: typing-blink 1.2s infinite;

      &:nth-child(2) {
        animation-delay: 0.2s;
      }
      &:nth-child(3) {
        animation-delay: 0.4s;
      }
    }
  }
}

@keyframes typing-blink {
  0%,
  60%,
  100% {
    opacity: 0.35;
  }
  30% {
    opacity: 1;
  }
}

.affection-toast {
  position: absolute;
  left: 50%;
  bottom: 64px;
  transform: translateX(-50%);
  padding: 6px 14px;
  border-radius: 999px;
  background: rgba(28, 28, 30, 0.85);
  color: #fff;
  font-size: 12px;
  letter-spacing: 1px;
  z-index: 6;
}

.toast-enter-active,
.toast-leave-active {
  transition:
    opacity 0.25s ease,
    transform 0.25s ease;
}

.toast-enter-from,
.toast-leave-to {
  opacity: 0;
  transform: translate(-50%, 8px);
}

.input-bar {
  flex: none;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px 10px;
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(14px);
  border-top: 1px solid var(--c-separator);

  input {
    flex: 1;
    height: 36px;
    padding: 0 14px;
    border: 1px solid var(--c-separator);
    border-radius: 18px;
    font-size: 14px;
    font-family: inherit;
    outline: none;
    background: #fff;

    &:focus {
      border-color: var(--c-ios-blue);
    }
  }
}

.send-btn {
  width: 34px;
  height: 34px;
  flex: none;
  border-radius: 50%;
  background: var(--c-ios-blue);
  color: #fff;
  font-size: 14px;
  display: flex;
  align-items: center;
  justify-content: center;

  &:disabled {
    opacity: 0.4;
  }
}
