
.app-screen {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: var(--c-phone-screen);
  min-height: 0;
}

.forum-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 12px 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.forum-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.gen-btn {
  padding: 10px 28px;
  border-radius: 999px;
  background: var(--c-ios-blue);
  color: #fff;
  font-size: 14px;

  &:disabled {
    opacity: 0.5;
  }

  i {
    margin-right: 6px;
  }
}

.forum-hint {
  font-size: 11px;
  color: var(--c-ios-gray);
}

.empty {
  padding: 30px 0;
  text-align: center;
  font-size: 13px;
  color: var(--c-ios-gray);
}

.post-card {
  background: #fff;
  border-radius: 14px;
  padding: 12px 14px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
  border-left: 3px solid var(--c-accent);

  &.expanded {
    border-left-color: var(--c-ios-blue);
  }
}

.post-head {
  width: 100%;
  text-align: left;
  display: block;
}

.post-title {
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 6px;
}

.post-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 6px;
}

.post-author {
  font-size: 11px;
  color: var(--c-success);
}

.post-floor {
  font-size: 11px;
  color: var(--c-ios-gray);
}

.post-reply-count {
  margin-left: auto;
  font-size: 11px;
  color: var(--c-ios-blue);

  i {
    margin-right: 3px;
  }
}

.post-body {
  font-size: 13px;
  line-height: 1.7;
  color: var(--c-text);
  white-space: pre-line;
}

/* —— 回复链 —— */

.reply-chain {
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px dashed var(--c-separator);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.reply-row {
  display: grid;
  grid-template-columns: auto auto 1fr;
  column-gap: 8px;
  align-items: baseline;
  padding-left: 8px;
  border-left: 2px solid var(--c-separator);
}

.reply-floor {
  font-size: 10px;
  color: var(--c-ios-gray);
  white-space: nowrap;
}

.reply-author {
  font-size: 11px;
  color: var(--c-success);
  white-space: nowrap;
}

.reply-body {
  grid-column: 1 / -1;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--c-text);
  white-space: pre-line;
}

.reply-empty {
  font-size: 12px;
  color: var(--c-ios-gray);
  text-align: center;
}

.reply-gen-btn {
  align-self: center;
  padding: 6px 18px;
  border-radius: 999px;
  background: rgba(10, 132, 255, 0.1);
  color: var(--c-ios-blue);
  font-size: 12px;

  &:disabled {
    opacity: 0.5;
  }

  i {
    margin-right: 5px;
  }
}

.error-hint {
  font-size: 12px;
  color: var(--c-danger);
  text-align: center;
}
