
.app-screen {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: var(--c-phone-screen);
  min-height: 0;
}

.wallpaper-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 8px 16px 20px;
}

.section {
  margin-bottom: 18px;
}

.section-title {
  font-size: 13px;
  color: var(--c-ios-gray);
  letter-spacing: 2px;
  margin-bottom: 10px;
}

.current-preview {
  height: 180px;
  border-radius: 18px;
  background-size: cover;
  background-position: center;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.18);
  display: flex;
  align-items: flex-end;
  padding: 12px;
}

.preview-label {
  color: #fff;
  font-size: 13px;
  text-shadow: 0 1px 6px rgba(0, 0, 0, 0.5);
}

.wall-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.wall-item {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 5px;
  align-items: center;

  &.active .wall-thumb {
    outline: 2.5px solid var(--c-ios-blue);
    outline-offset: 2px;
  }
}

.wall-thumb {
  width: 100%;
  aspect-ratio: 9 / 16;
  border-radius: 14px;
  background-size: cover;
  background-position: center;
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.12);

  &--default {
    background-image:
      radial-gradient(120% 90% at 20% 0%, rgba(229, 138, 165, 0.35), transparent 55%),
      radial-gradient(120% 100% at 90% 100%, rgba(167, 139, 250, 0.4), transparent 60%),
      linear-gradient(165deg, #3a3040, #241d2c 55%, #17121c);
  }

  &--upload {
    background: #fff;
    border: 2px dashed var(--c-separator);
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--c-ios-blue);
    font-size: 24px;
    box-shadow: none;
  }
}

.wall-name {
  font-size: 11px;
  color: var(--c-text);
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wall-check {
  position: absolute;
  top: -5px;
  right: -5px;
  color: var(--c-ios-blue);
  background: #fff;
  border-radius: 50%;
  font-size: 17px;
}

.hint {
  margin-top: 10px;
  font-size: 12px;
  color: var(--c-ios-gray);
  line-height: 1.7;
}
