
.launcher {
  position: fixed;
  right: 22px;
  bottom: 22px;
  z-index: 9990;
  width: 58px;
  height: 58px;
  border-radius: 50%;
  background: linear-gradient(145deg, #4a4a52, var(--c-launcher));
  color: #fff;
  font-size: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-launcher);
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;

  &:hover {
    transform: translateY(-2px) scale(1.05);
    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.45);
  }
}

.launcher-pulse {
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.35);
  animation: launcher-pulse 2.4s ease-out infinite;
  pointer-events: none;
}

@keyframes launcher-pulse {
  0% {
    transform: scale(0.9);
    opacity: 0.8;
  }
  100% {
    transform: scale(1.5);
    opacity: 0;
  }
}

.phone-overlay {
  position: fixed;
  inset: 0;
  z-index: 9991;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(10, 10, 12, 0.45);
  backdrop-filter: blur(3px);
}

.phone-enter-active,
.phone-leave-active {
  transition:
    opacity 0.35s ease,
    transform 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}

.phone-enter-from,
.phone-leave-to {
  opacity: 0;
  transform: translateY(40px) scale(0.92);
}

.phone-enter-to,
.phone-leave-from {
  opacity: 1;
  transform: translateY(0) scale(1);
}
